//! js_deno generator — STUB.
//!
//! Deno.dlopen-based code generation is not yet implemented.
//! Both host and guest generation emit a single README file explaining
//! that this variant is a planned stub.

use crate::error::CodegenError;
use crate::generators::CodeGenerator;
use crate::generators::GeneratedFile;
use crate::generators::GeneratedFiles;
use crate::ir::ValidatedIr;
use std::path::PathBuf;

pub(crate) struct JsDenoGenerator {
    pub typescript_mode: bool,
}

const STUB_CONTENT: &str = "# THIS FILE IS AUTO-GENERATED BY polyplugc\n\
     # DO NOT EDIT BY HAND\n\
     \n\
     # ts-deno/js-deno code generation is not yet implemented.\n\
     # This is a planned stub for the Deno.dlopen-based plugin variant.\n\
     # See Epic 10 scope notes in polyplug_prd.md.\n";

impl CodeGenerator for JsDenoGenerator {
    fn language_name(&self) -> &'static str {
        if self.typescript_mode {
            "ts-deno"
        } else {
            "js-deno"
        }
    }

    fn generate_host(
        &self,
        _ir: &ValidatedIr,
        files: &mut GeneratedFiles,
    ) -> Result<(), CodegenError> {
        files.files.push(GeneratedFile {
            path: PathBuf::from("STUB_README.md"),
            content: STUB_CONTENT.to_owned(),
        });
        Ok(())
    }

    fn generate_guest(
        &self,
        _ir: &ValidatedIr,
        files: &mut GeneratedFiles,
    ) -> Result<(), CodegenError> {
        files.files.push(GeneratedFile {
            path: PathBuf::from("STUB_README.md"),
            content: STUB_CONTENT.to_owned(),
        });
        Ok(())
    }
}
